#define MAX_DIST 100.
#define SURF_DIST .001
#define EPS .0001
#define PI 3.14
#define PI2 6.28
#define saturate(a) clamp(a,0.,1.)
#define S(a,b,t) smoothstep(a,b,t)
#define TS(a,b,c,d,t) smoothstep(a,b,t) * smoothstep(d,c,t)
#define REP(p,r) mod(p,r) - r * .5  

#define MAT_BASE 1.
#define MAT_OUTER_1 2.
#define MAT_OUTER_2 3.

/*
 * utilities
 */

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

vec2 pmod(vec2 p, float s) {
    float a = PI / s - atan(p.x, p.y);
    float n = PI2 / s;
    a = floor(a / n) * n;
    p *= rot(-a);
    return p;
}

float sdBox(vec3 p, vec3 b) {
    vec3 q = abs(p) - b;
    return length(max(q, 0.)) + min(max(q.x, max(q.y, q.z)), 0.);
}

vec2 opUnion2(vec2 a, vec2 b) {
	return a.x < b.x ? a : b;
}

bool isMat(float mat, float m) {
    return mat < m + .5;
}

/* end utilities */

vec2 scene(vec3 p) {
    vec2 res = vec2(100000., -1.);
    float t = iTime;

    vec3 q = p;





    float rep = 8.;
    vec3 id = floor(q * rep);
    q.z = REP(q.z, rep);

    q.xy = pmod(q.xy, 6.);
    q.y -= 6.2;
    q.yz*=mat2(cos(iTime),sin(iTime),-sin(iTime), cos(iTime));
    q.xz*=mat2(cos(iTime),sin(iTime),-sin(iTime), cos(iTime));
    for(float i = 0.; i < 3.; i++) {

        float s = .8;
        float sw = .95;
        float sh = .07;
        res = opUnion2(res, vec2(sdBox(q, vec3(s, s, s)) - .04, 1.));
        res = opUnion2(res, vec2(sdBox(q, vec3(sw, sh, sw)) - .01, 2.));
        res = opUnion2(res, vec2(sdBox(q, vec3(sh, sw, sw)) - .01, 3.));
    }


    return res;
}

vec3 getNormal(vec3 p) {
	vec2 e = vec2(1., -1.) * EPS;
    return normalize(
        e.xyy * scene(p + e.xyy).x+
        e.yxy * scene(p + e.yxy).x+
        e.yyx * scene(p + e.yyx).x+
        e.xxx * scene(p + e.xxx).x
    );
}

vec2 raymarch(vec3 ro, vec3 rd, float side, inout vec3 emission) {
    float accDist = 0.;    
    float mat = 0.;
    float t = iTime;

    for(int i = 0; i < 99; i++) {
        vec3 p = ro + rd * accDist;
        vec2 result = scene(p);
        float dist = result.x * side;
        mat = result.y;
        if(abs(dist) < SURF_DIST || accDist > MAX_DIST) {
            break;
        }
        dist *= .5;
        accDist += dist;      

        emission += exp(abs(dist) * -.01) * vec3(.2, .4, .9) * .015;

        float ag =  pow(sin(.2 + p.z * .2 - t * 1.4) * 1.5, 4.) + .1;

        if(isMat(mat, MAT_BASE)) {
            // emission += .001 / abs(dist) * vec3(.01, .01, .05) * ag;
        } else if(isMat(mat, MAT_OUTER_1 + .5)) {
            emission += .006 / abs(dist) * vec3(.1, .9, 1. + sin(t + .2) * .4) * ag;
        } else if(isMat(mat, MAT_OUTER_2 + .5)) {
            emission += .006 / abs(dist) * vec3(.2 + sin(t + .5) * .1, .4, 1. + sin(t + 3.) * .8) * ag;
        }
    }

    return vec2(accDist, mat);
}


vec3 getRayDir(vec2 uv, vec3 p, vec3 l, float z) {
    vec3 forward = normalize(l - p);
    vec3 right = normalize(cross(vec3(0., 1., 0.), forward));
    vec3 up = normalize(cross(forward, right));

    return normalize(right * uv.x + up * uv.y + forward * z);        
}
float happy_star(vec2 uv, float anim)
{
    uv = abs(uv);
    vec2 pos = min(uv.xy/uv.yx, anim);
    float p = (2.0 - pos.x - pos.y);
    return (2.0+p*(p*p-1.5)) / (uv.x+uv.y);      
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float t = iTime;

    vec2 uv = (fragCoord.xy * 2. - iResolution.xy) / min(iResolution.x, iResolution.y);

   float t2 = iTime * .1 + ((.25 + .05 * sin(iTime * .1))/(length(uv.xy) + .07)) * 2.2;
	float si = sin(t2);
	float co = cos(t2);
	mat2 ma = mat2(co, si, -si, co);

	float v1, v2, v3;
	v1 = v2 = v3 = 0.0;

	float s = 0.0;
	for (int i = 0; i < 90; i++)
	{
		vec3 p = s * vec3(uv, 0.0);

		p += vec3(.22, .3, s - 1.5 - sin(iTime * .13) * .1);
		for (int i = 0; i < 8; i++)	p = abs(p) / dot(p,p) - 0.659;
		v1 += dot(p,p) * .0015 * (1.8 + sin(length(uv.xy * 13.0) + .5  - iTime * .2));
		v2 += dot(p,p) * .0013 * (1.5 + sin(length(uv.xy * 14.5) + 1.2 - iTime * .3));
		v3 += length(p.xy*10.) * .0003;
		s  += .035;
	}

	float len = length(uv);
	v1 *= smoothstep(.7, .0, len);
	v2 *= smoothstep(1.5, .0, len);
	v3 *= smoothstep(.9, .0, len);

	vec3 col2 = vec3( v3 * (1.5 + sin(iTime * .2) * .4),
					(v1 + v3) * .3,
					 v2) + smoothstep(0.2, .0, len) * .85 + smoothstep(.0, .6, v3) * .3;
    vec3 ro = vec3(
         1.,
        1. + 0.,
        -10.
    );

ro.z+=iTime;
    vec3 rd = getRayDir(uv, ro, vec3(0.), 1.5);
    rd.xy*=mat2(cos(iTime),sin(iTime),-sin(iTime), cos(iTime));
    vec3 emission = vec3(0.);

    vec2 result = raymarch(ro, rd, 1., emission);
    float dist = result.x;
    float mat = result.y;

    vec3 col = vec3(0.);

    if(dist < MAX_DIST) {    
        vec3 p = ro + rd * dist;
        vec3 l = normalize(vec3(1., 1., -1.));
        vec3 n = getNormal(p);    
        vec3 r = reflect(rd, n);

        float diffuse = dot(l, n) * .5 + .5;
        vec3 diffuseColor = vec3(0.);

        if(isMat(mat, MAT_BASE)) {
            diffuseColor  = vec3(.01);
        } else if(isMat(mat, MAT_OUTER_1)) {
            diffuseColor = vec3(0.);
        } else if(isMat(mat, MAT_OUTER_2)) {
            diffuseColor = vec3(0.);
        }

        col = diffuse * diffuseColor;       
    }

    col += emission;

    col *= exp(-dist * .3);

    col = pow(col, vec3(.4545));

    col *= 1. - smoothstep(1.2, 2., length(uv));

    fragColor = vec4(col+col2, 1.);

     uv *= 2.0 * ( cos(iTime * 2.0) -2.5); // scale
    float anim = sin(iTime * 12.0) * 0.1 + 1.0;  // anim between 0.9 - 1.1 
    fragColor+= vec4(happy_star(uv, anim) * vec3(0.35,0.2,0.55), 1.0);
}
